package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;import java.util.*;
/** Realtime tracks are samples; a newer explicit empty sample must clear an old Steam game. */
final class PeerActivity {
 static long stamp(JSONObject m){Object raw=m.opt("online_at");if(raw instanceof Number)return ((Number)raw).longValue();String value=m.optString("online_at","");try{return Long.parseLong(value);}catch(Exception ignored){return MessageTime.epoch(value);}}
 static boolean fresh(JSONObject m,long now){long t=stamp(m);return t<=0||(t<=now+300000&&now-t<=90000);}
 static JSONObject current(JSONArray metas,long now){if(metas==null)return null;List<JSONObject> visible=new ArrayList<>(),hidden=new ArrayList<>();for(int i=0;i<metas.length();i++){JSONObject m=metas.optJSONObject(i);if(m==null||!fresh(m,now))continue;if("invisivel".equals(m.optString("status")))hidden.add(m);else visible.add(m);}Collections.sort(visible,(a,b)->Long.compare(stamp(b),stamp(a)));List<JSONObject> known=new ArrayList<>();for(JSONObject m:visible){if(!m.optBoolean("activity_shared",true))continue;if(!m.optString("jogo","").isEmpty()&&"pc".equals(m.optString("jogo_fonte")))return m;if(m.optBoolean("activity_known",true))known.add(m);}if(!known.isEmpty()){if(stamp(known.get(0))>0)return known.get(0);for(JSONObject m:known)if(!m.optString("jogo","").isEmpty())return m;return known.get(0);}return !visible.isEmpty()?visible.get(0):!hidden.isEmpty()?hidden.get(0):null;}
 static JSONArray merge(JSONArray current,JSONArray incoming,boolean remove){JSONArray result=new JSONArray();if(incoming==null)return current==null?result:current;if(!remove)for(int i=0;i<incoming.length();i++)if(incoming.optJSONObject(i)!=null)result.put(incoming.optJSONObject(i));if(current!=null)for(int i=0;i<current.length();i++){JSONObject old=current.optJSONObject(i);if(old==null)continue;boolean replaced=false;for(int j=0;j<incoming.length();j++){JSONObject next=incoming.optJSONObject(j);if(next!=null&&(old.optString("phx_ref").equals(next.optString("phx_ref"))||(!remove&&old.optString("phx_ref").equals(next.optString("phx_ref_prev","__none__")))))replaced=true;}if(!replaced)result.put(old);}return result;}
 static String label(JSONObject meta){String status=meta.optString("status","online"),base=ProfileStatus.LABELS[ProfileStatus.index(status)];String game=meta.optBoolean("activity_shared",true)?meta.optString("jogo",""):"";return game.isEmpty()?base:("ausente".equals(status)||"dnd".equals(status)?base+" · ":"")+"Jogando · "+game;}
}
